diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..ed7a198
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,62 @@
+import { isDate } from "../dates.js";
+import { memoryStore } from "../db/store.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { consume } from "../domain/batches.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const columns = ["ticket", "soldAt", "dishId", "qty"];
+const csvLine = /^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/;
+const instant = /^\d{4}-\d\d-\d\dT(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-]\d\d:\d\d)$/i;
+
+function invalid(row, reason) {
+  return new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+}
+
+/** Imports complete tickets atomically and counts newly sold portions. */
+export function importSales(store, csv) {
+  if (typeof csv !== "string") throw invalid(1, "csv must be text");
+  const lines = csv.split(/\r?\n/);
+  const header = parseCsv(lines[0])[0]?.map((field) => field.trim()) ?? [];
+  if (!csvLine.test(lines[0]) || header.length !== columns.length || !columns.every((c) => header.includes(c)))
+    throw invalid(1, "expected ticket,soldAt,dishId,qty");
+
+  const staged = memoryStore(store.data);
+  const known = new Set(staged.data.sales.map((s) => s.ticket));
+  const imported = new Set();
+  let dishes = 0;
+  for (let i = 1; i < lines.length; i++) {
+    if (!lines[i].trim()) continue;
+    if (!csvLine.test(lines[i])) throw invalid(i + 1, "malformed CSV");
+    const [fields] = parseCsv(lines[i]);
+    if (fields.length !== header.length) throw invalid(i + 1, "wrong number of fields");
+    const row = Object.fromEntries(header.map((key, j) => [key, fields[j].trim()]));
+    const { ticket, soldAt } = row;
+    const dishId = Number(row.dishId);
+    const qty = Number(row.qty);
+    if (!ticket) throw invalid(i + 1, "missing ticket");
+    if (!instant.test(soldAt) || !Number.isFinite(Date.parse(soldAt)) || !isDate(soldAt.slice(0, 10)))
+      throw invalid(i + 1, "invalid soldAt");
+    if (!/^\d+$/.test(row.qty) || !Number.isSafeInteger(qty) || qty < 1) throw invalid(i + 1, "invalid qty");
+    if (!/^\d+$/.test(row.dishId) || !Number.isSafeInteger(dishId) || dishId < 1) throw invalid(i + 1, "invalid dishId");
+    try {
+      const dish = getDish(staged, dishId);
+      if (known.has(ticket)) continue;
+      const at = new Date(soldAt).toISOString();
+      const ingredients = scaled(getRecipe(staged, dish.recipeId), qty);
+      for (const need of ingredients) {
+        if (need.qty > 0) consume(staged, need.itemId, need.qty, { at, ref: `sale:${ticket}` });
+      }
+      staged.data.sales.push({ id: staged.nextId("sale"), ticket, soldAt: at, dishId, qty, ingredients });
+      imported.add(ticket);
+      dishes += qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      if (error.code === "not_enough_stock") throw new AppError("sale_shortage", { ...error.params, row: i + 1 });
+      throw invalid(i + 1, error.code === "not_found" ? "unknown dish or recipe" : error.code);
+    }
+  }
+  store.data = staged.data;
+  return { tickets: imported.size, dishes };
+}
